<?php require 'includes/auth.php';require 'config/database.php';require 'includes/csrf.php';if($_SERVER['REQUEST_METHOD']==='POST'){check();$v=[trim($_POST['code']),trim($_POST['name']),$_POST['dob']?:null,$_POST['gender'],trim($_POST['address']),$_POST['admission'],$_POST['status']];if($_POST['id']){$v[]=(int)$_POST['id'];$pdo->prepare('UPDATE prisoners SET prisoner_code=?,full_name=?,date_of_birth=?,gender=?,address=?,admission_date=?,status=? WHERE id=?')->execute($v);}else{$pdo->prepare('INSERT INTO prisoners(prisoner_code,full_name,date_of_birth,gender,address,admission_date,status) VALUES(?,?,?,?,?,?,?)')->execute($v);}header('Location: prisoners.php');exit;}$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM prisoners WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$search=trim($_GET['q']??'');$s=$pdo->prepare('SELECT * FROM prisoners WHERE prisoner_code LIKE ? OR full_name LIKE ? ORDER BY id DESC');$s->execute(["%$search%","%$search%"]);$rows=$s->fetchAll();$title='Prisoners';require 'includes/header.php';?><div class="row g-4"><div class="col-lg-4"><div class="box"><h4><?=$edit?'Edit':'Register'?> Prisoner</h4><form method="post"><input type="hidden" name="token" value="<?=token()?>"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><label class="form-label mt-2">Code</label><input class="form-control" name="code" required value="<?=htmlspecialchars($edit['prisoner_code']??'')?>"><label class="form-label mt-2">Full Name</label><input class="form-control" name="name" required value="<?=htmlspecialchars($edit['full_name']??'')?>"><label class="form-label mt-2">Date of Birth</label><input type="date" class="form-control" name="dob" value="<?=$edit['date_of_birth']??''?>"><label class="form-label mt-2">Gender</label><select class="form-select" name="gender"><?php foreach(['Male','Female','Other'] as $x):?><option <?=($edit['gender']??'')===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select><label class="form-label mt-2">Address</label><textarea class="form-control" name="address"><?=htmlspecialchars($edit['address']??'')?></textarea><label class="form-label mt-2">Admission Date</label><input type="date" class="form-control" name="admission" required value="<?=$edit['admission_date']??date('Y-m-d')?>"><label class="form-label mt-2">Status</label><select class="form-select" name="status"><?php foreach(['Active','Released','Transferred'] as $x):?><option <?=($edit['status']??'Active')===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select><button class="btn btn-primary mt-3">Save</button></form></div></div><div class="col-lg-8"><div class="box"><h2>Prisoners</h2><form class="d-flex mb-3"><input class="form-control me-2" name="q" value="<?=htmlspecialchars($search)?>" placeholder="Search"><button class="btn btn-dark">Search</button></form><div class="table-responsive"><table class="table table-hover"><tr><th>Code</th><th>Name</th><th>Admission</th><th>Status</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['prisoner_code'])?></td><td><?=htmlspecialchars($r['full_name'])?></td><td><?=$r['admission_date']?></td><td><?=$r['status']?></td><td><a class="btn btn-sm btn-outline-primary" href="?edit=<?=$r['id']?>">Edit</a></td></tr><?php endforeach;?></table></div></div></div></div><?php require 'includes/footer.php';?>